# IPTVPremium: nitidez adaptativa e FSR 1/RCAS no player. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/PlaybackModels.kt'; Allowed = @('7C041C645D6858C5C7828769F9EF84968FEA4861733014026F2B5165099FC513'); MayCreate = $false; After = '356AFDD719DD71FCB0C283E2CACD818A486BC80F8CCAD0419CD831F825F6860D'; PayloadHash = '356AFDD719DD71FCB0C283E2CACD818A486BC80F8CCAD0419CD831F825F6860D'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/PlaybackEngineContract.kt'; Allowed = @('C0D19D88D5045383B039730E4F1CEFC9E6B3711684FD278549C7E49F2EFEBF03'); MayCreate = $false; After = 'D3DE5EE787CE1000367E1917EF8F3AB4BDF943B3977543567DFD8DEFD0D9C7B0'; PayloadHash = 'D3DE5EE787CE1000367E1917EF8F3AB4BDF943B3977543567DFD8DEFD0D9C7B0'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/PlaybackController.kt'; Allowed = @('D153C9B646D0F4AF11CF2081F7EA8FA41563DDD25A90E36472FBD8738035855D'); MayCreate = $false; After = 'A12A8364FA6C6F0DFFE9BD2247C4180308677DEE224EB9B4CCA8CF9C0A47C239'; PayloadHash = 'A12A8364FA6C6F0DFFE9BD2247C4180308677DEE224EB9B4CCA8CF9C0A47C239'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/Media3PlaybackAdapter.kt'; Allowed = @('D3389ECE98F3E9EF57FA52388824B63E66409EEA1145B0F8D5718DDA0C21EF78'); MayCreate = $false; After = '5828C644828E75634A7EF9F72766B2F4011712843B068EFEBE9ED3C169DC6863'; PayloadHash = '5828C644828E75634A7EF9F72766B2F4011712843B068EFEBE9ED3C169DC6863'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/PlaybackScreen.kt'; Allowed = @('62D0C3F984ECC1262447E6B0AE7D40D7DD8132C9C6C701E73A29CE0ECD00E4A6'); MayCreate = $false; After = 'C797E68E2AC8D39B0C00C3C15BDCD8A9090399366B7DB6959F8F642241B4902F'; PayloadHash = 'C797E68E2AC8D39B0C00C3C15BDCD8A9090399366B7DB6959F8F642241B4902F'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/PlaybackImageEnhancement.kt'; Allowed = @(); MayCreate = $true; After = 'F3E7875EA613E7D07643068289CA88659F3731C5FDCCA214014F3E6409CE9F29'; PayloadHash = 'F3E7875EA613E7D07643068289CA88659F3731C5FDCCA214014F3E6409CE9F29'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/player/PlaybackImageEffects.kt'; Allowed = @('09DE39B540CD04B1A4EC501CF2C707F07252B716EAC4451A77E3BCF2AE0B3E85'); MayCreate = $true; After = 'D9283AD762EB31BBF65129F46FC7A6590923A1946BB3F2CF616944799E9A1CBE'; PayloadHash = 'D9283AD762EB31BBF65129F46FC7A6590923A1946BB3F2CF616944799E9A1CBE'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/SettingsPreferences.kt'; Allowed = @('1EDE7AFAEFE7F5EA465D6E692441978BA4EB98C9125FECD42E437758E6715ED9'); MayCreate = $false; After = '5DB4DB38436692F3F35D26E3525E7721A95F28B8080E61168D9DC861D99B1C23'; PayloadHash = '5DB4DB38436692F3F35D26E3525E7721A95F28B8080E61168D9DC861D99B1C23'; Data = '' },
    @{ Path = 'app/src/main/assets/shaders/image_vertex.glsl'; Allowed = @(); MayCreate = $true; After = '9EDEDEB93A39EA424092C51B245E1632C5643DE1E292D10205FD4FEF42700332'; PayloadHash = '9EDEDEB93A39EA424092C51B245E1632C5643DE1E292D10205FD4FEF42700332'; Data = 'H4sIAAAAAAACA0ssKSnKTCotSVUoS002UUgMyC/OLMnMz7PmKkssqszMSweJGymUhaRWAIXyM1MUchMz8zQ0FaoV0nPiYaoVbJF0ghUji+hVVCpoKRjomSpog0hrhVouADi3vVx3AAAA' },
    @{ Path = 'app/src/main/assets/shaders/image_copy.glsl'; Allowed = @(); MayCreate = $true; After = '573A034F81E0E4FCD090819DCBB4C013C31132946CF2BC4D1CC036FA3E53F0E9'; PayloadHash = '573A034F81E0E4FCD090819DCBB4C013C31132946CF2BC4D1CC036FA3E53F0E9'; Data = 'H4sIAAAAAAACA02MsQrCMBRF93zFHVtwyhqcLP6A7hLqa/ogyQuvaWgR/92ii+M9h3OL0sgLS8bMYS6YovjqzJp5Ek1YfCqR1A5Y77TdfsuZ5nXnHNBotGiHOZDwE8lz7nq8EOLjqj5cJIrijEpbXZXs0P3dnL5l7/A2H2rXM7eGAAAA' },
    @{ Path = 'app/src/main/assets/shaders/image_rcas.glsl'; Allowed = @(); MayCreate = $true; After = 'F470E553E7F230F3036B890A2D45E0D98382930B60CEC0D07695D67C379DAEC9'; PayloadHash = 'F470E553E7F230F3036B890A2D45E0D98382930B60CEC0D07695D67C379DAEC9'; Data = '' },
    @{ Path = 'app/src/main/assets/shaders/image_easu.glsl'; Allowed = @(); MayCreate = $true; After = '3EA37B40BF1132B16B95A0325715E2EFE1BD7A5F1B9154A87D085A7AE21F779C'; PayloadHash = '3EA37B40BF1132B16B95A0325715E2EFE1BD7A5F1B9154A87D085A7AE21F779C'; Data = '' },
    @{ Path = 'app/src/main/assets/FSR1-NOTICE.txt'; Allowed = @(); MayCreate = $true; After = '5A1726A04F675298F61A30C07FDF14679B5A0AA89FD7CB2A757504CC1BBF78F0'; PayloadHash = '5A1726A04F675298F61A30C07FDF14679B5A0AA89FD7CB2A757504CC1BBF78F0'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/core/player/PlaybackImageDeviceTest.kt'; Allowed = @(); MayCreate = $true; After = 'FBB0E58D9A20025D3F939EFD1DAA092AFB06BE304E80A2847846EA9EE75B04D9'; PayloadHash = 'FBB0E58D9A20025D3F939EFD1DAA092AFB06BE304E80A2847846EA9EE75B04D9'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/core/player/PlaybackImageButtonDeviceTest.kt'; Allowed = @(); MayCreate = $true; After = '2DB3380C7D3AC00FCA4D4F2346D3EF6D2BC44D90584F66A9BFA9AAB8EFA4275E'; PayloadHash = '2DB3380C7D3AC00FCA4D4F2346D3EF6D2BC44D90584F66A9BFA9AAB8EFA4275E'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = Get-TextHash $original
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}

# Acrescenta somente a dependencia do Media3, preservando o restante do build local.
$buildPath = Join-Path $root 'app/build.gradle.kts'
$buildOriginal = [IO.File]::ReadAllBytes($buildPath)
$buildText = [Text.Encoding]::UTF8.GetString($buildOriginal)
$effectLine = 'implementation("androidx.media3:media3-effect:$media3Version")'
$effectPattern = '(?m)^[ \t]*implementation\("androidx\.media3:media3-effect:\$media3Version"\)[ \t]*\r?$'
if ([regex]::Matches($buildText, 'val\s+media3Version\s*=\s*"1\.11\.1"').Count -ne 1) {
    throw 'Esta atualizacao requer Media3 1.11.1. Nada foi alterado.'
}
if ([regex]::Matches($buildText, $effectPattern).Count -eq 0) {
    if ($buildText.Contains('media3-effect') -or [regex]::Matches($buildText, 'val\s+media3Version\s*=\s*"1\.11\.1"').Count -ne 1) {
        throw 'A dependencia Media3 usa uma configuracao diferente. Nada foi alterado.'
    }
    $uiPattern = '(?m)^[ \t]*implementation\("androidx\.media3:media3-ui:\$media3Version"\)[ \t]*'
    $anchors = [regex]::Matches($buildText, $uiPattern)
    if ($anchors.Count -ne 1) { throw 'Nao foi possivel localizar a dependencia Media3. Nada foi alterado.' }
    $anchor = $anchors[0]
    $newline = if ($buildText.Contains("`r`n")) { "`r`n" } else { "`n" }
    $indent = [regex]::Match($anchor.Value, '^[ \t]*').Value
    $at = $anchor.Index + $anchor.Length
    $updatedBuild = $buildText.Substring(0, $at) + $newline + $indent + $effectLine + $buildText.Substring($at)
    $buildBytes = [Text.Encoding]::UTF8.GetBytes($updatedBuild)
    $pending += @{ Path = $buildPath; Relative = 'app/build.gradle.kts'; Bytes = $buildBytes; Original = $buildOriginal; Present = $true; Hash = (Get-BytesHash $buildBytes) }
}

if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/imagem-player-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: botao Nitidez, modo Leve e FSR 1 + RCAS no Exo Player.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
